/**
 * Gold split generator — spec 003, US2 (FR-003, SC-001).
 *
 * The product of this module is DETERMINISM: a split that cannot be
 * regenerated byte-for-byte makes every downstream metric unfalsifiable
 * (constitution I). The tests below therefore pin the reproducibility
 * guarantees first and the shape of the data afterwards.
 */
import { createHash } from 'node:crypto';
import { mkdtemp, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import fastCheck from 'fast-check';
import { canonicalJson } from '@vision-lens/contracts';
import {
  CAPTURE_GROUP_OVERFLOW_REASON_PREFIX,
  computeManifestHash,
  computeSplitCapacities,
  generateSplitManifest,
  mulberry32,
  serializeSplitManifest,
  validateSplitManifest,
  validateSplitManifestHashes,
  type SplitItem,
  type SplitManifest,
} from '../../src/benchmark/splits.js';

function makeItem(id: string, overrides: Partial<SplitItem> = {}): SplitItem {
  return {
    id,
    class: 'pcb1',
    anomaly: 'normal',
    sha256: createHash('sha256').update(id).digest('hex'),
    path: `${id}.JPG`,
    ...overrides,
  };
}

/** 30 items across 2 classes × 2 anomaly labels, two capture groups each. */
function makeDataset(): SplitItem[] {
  const items: SplitItem[] = [];
  for (const className of ['pcb1', 'pcb2']) {
    for (const anomaly of ['normal', 'anomalous'] as const) {
      for (let index = 0; index < 8; index += 1) {
        const id = `${className}/${anomaly}/${String(index).padStart(3, '0')}`;
        items.push(
          makeItem(id, {
            class: className,
            anomaly,
            group: `${className}/${anomaly}/session-${index % 2}`,
          }),
        );
      }
    }
  }
  return items;
}

const BASE_OPTIONS = {
  id: 'test.gold',
  datasetId: 'test-dataset',
  seed: 42,
} as const;

/* ------------------------------------------------------------------ *
 * 1. Byte-stability (SC-001)
 * ------------------------------------------------------------------ */

describe('split manifest — byte-stability', () => {
  it('regenerates byte-identically for the same seed and inputs', () => {
    const items = makeDataset();
    const first = serializeSplitManifest(generateSplitManifest({ ...BASE_OPTIONS, items }));
    const second = serializeSplitManifest(generateSplitManifest({ ...BASE_OPTIONS, items }));
    expect(second).toBe(first);
    expect(first.length).toBeGreaterThan(0);
  });

  it('produces a DIFFERENT manifest for a different seed (the seed is really used)', () => {
    const items = makeDataset();
    const seed42 = serializeSplitManifest(
      generateSplitManifest({ ...BASE_OPTIONS, seed: 42, items }),
    );
    const seed43 = serializeSplitManifest(
      generateSplitManifest({ ...BASE_OPTIONS, seed: 43, items }),
    );
    expect(seed43).not.toBe(seed42);
    expect(seed43).not.toEqual(seed42);
  });

  it('carries no timestamp field (a timestamp would break byte-stability)', () => {
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items: makeDataset() });
    expect(Object.keys(manifest)).toEqual([
      'schemaVersion',
      'id',
      'datasetId',
      'seed',
      'ratios',
      'strata',
      'assignments',
      'notes',
      'manifestHash',
    ]);
    expect(JSON.stringify(manifest)).not.toMatch(/generatedAt|timestamp|createdAt/i);
  });
});

/* ------------------------------------------------------------------ *
 * 2. Key-order independence
 * ------------------------------------------------------------------ */

describe('split manifest — key-order independence', () => {
  it('is independent of the order in which the items are supplied', () => {
    const items = makeDataset();
    const shuffled = items.slice().reverse();
    const ordered = serializeSplitManifest(generateSplitManifest({ ...BASE_OPTIONS, items }));
    const reversed = serializeSplitManifest(
      generateSplitManifest({ ...BASE_OPTIONS, items: shuffled }),
    );
    expect(reversed).toBe(ordered);
  });

  it('is independent of the order in which the notes are supplied', () => {
    const notes = [
      { id: 'pcb1/normal/007', reason: 'known-bad: blurry capture' },
      { id: 'pcb2/anomalous/003', reason: 'known-bad: mislabelled' },
    ];
    const items = makeDataset();
    const forward = serializeSplitManifest(
      generateSplitManifest({ ...BASE_OPTIONS, items, notes }),
    );
    const backward = serializeSplitManifest(
      generateSplitManifest({ ...BASE_OPTIONS, items, notes: notes.slice().reverse() }),
    );
    expect(backward).toBe(forward);
  });
});

/* ------------------------------------------------------------------ *
 * 3. Stratification invariants (property test)
 * ------------------------------------------------------------------ */

describe('split manifest — stratification invariants', () => {
  const fc = fastCheck;

  it('keeps per-stratum counts and the global 60/20/20 proportions (property)', () => {
    const tolerance = 0.05 + 1e-9; // documented tolerance for strata >= 10 items

    fc.assert(
      fc.property(
        fc.array(fc.integer({ min: 10, max: 40 }), { minLength: 1, maxLength: 6 }),
        (sizes: number[]) => {
          const items: SplitItem[] = [];
          sizes.forEach((size, stratumIndex) => {
            for (let index = 0; index < size; index += 1) {
              items.push(
                makeItem(`c${stratumIndex}/n/${String(index).padStart(3, '0')}`, {
                  class: `c${stratumIndex}`,
                  anomaly: 'normal',
                }),
              );
            }
          });

          const manifest = generateSplitManifest({ ...BASE_OPTIONS, items });
          const total = manifest.assignments.length;
          expect(total).toBe(items.length);

          // Every input item appears in exactly one assignment.
          expect(new Set(manifest.assignments.map((a) => a.id)).size).toBe(items.length);

          // The recorded per-stratum counts match the assignments.
          for (const stratum of manifest.strata) {
            const inStratum = manifest.assignments.filter(
              (a) => a.class === stratum.class && a.anomaly === stratum.anomaly,
            );
            expect(inStratum.length).toBe(stratum.total);
            expect(inStratum.filter((a) => a.split === 'train').length).toBe(stratum.train);
            expect(inStratum.filter((a) => a.split === 'val').length).toBe(stratum.val);
            expect(inStratum.filter((a) => a.split === 'test').length).toBe(stratum.test);
          }

          // Global proportions stay within the documented tolerance.
          const train = manifest.assignments.filter((a) => a.split === 'train').length;
          const val = manifest.assignments.filter((a) => a.split === 'val').length;
          const test = manifest.assignments.filter((a) => a.split === 'test').length;
          expect(Math.abs(train / total - 0.6)).toBeLessThanOrEqual(tolerance);
          expect(Math.abs(val / total - 0.2)).toBeLessThanOrEqual(tolerance);
          expect(Math.abs(test / total - 0.2)).toBeLessThanOrEqual(tolerance);
        },
      ),
      { seed: 20240101, numRuns: 50 },
    );
  });
});

/* ------------------------------------------------------------------ *
 * 4. Small strata — the pinned rounding rule
 * ------------------------------------------------------------------ */

describe('split manifest — small strata rounding rule', () => {
  it('applies the documented largest-remainder rule for a 1-item stratum', () => {
    const manifest = generateSplitManifest({
      ...BASE_OPTIONS,
      items: [makeItem('solo/normal/000', { class: 'solo', anomaly: 'normal' })],
    });
    expect(manifest.strata).toEqual([
      { class: 'solo', anomaly: 'normal', total: 1, train: 1, val: 0, test: 0 },
    ]);
    expect(manifest.assignments).toHaveLength(1);
  });

  it('applies the documented largest-remainder rule for a 2-item stratum', () => {
    const manifest = generateSplitManifest({
      ...BASE_OPTIONS,
      items: [
        makeItem('solo/normal/000', { class: 'solo', anomaly: 'normal' }),
        makeItem('solo/normal/001', { class: 'solo', anomaly: 'normal' }),
      ],
    });
    expect(manifest.strata[0]).toMatchObject({ total: 2, train: 1, val: 1, test: 0 });
    expect(manifest.assignments).toHaveLength(2);
  });

  it('records the quota it used for every stratum size', () => {
    expect(computeSplitCapacities(1)).toEqual({ train: 1, val: 0, test: 0 });
    expect(computeSplitCapacities(2)).toEqual({ train: 1, val: 1, test: 0 });
    expect(computeSplitCapacities(3)).toEqual({ train: 2, val: 1, test: 0 });
    expect(computeSplitCapacities(4)).toEqual({ train: 2, val: 1, test: 1 });
    expect(computeSplitCapacities(5)).toEqual({ train: 3, val: 1, test: 1 });
    expect(computeSplitCapacities(10)).toEqual({ train: 6, val: 2, test: 2 });
    expect(computeSplitCapacities(30)).toEqual({ train: 18, val: 6, test: 6 });
  });

  it('never loses an item, whatever the stratum size', () => {
    for (const size of [1, 2, 3, 4, 5, 7, 11, 13, 29]) {
      const items = Array.from({ length: size }, (_unused, index) =>
        makeItem(`s/normal/${String(index).padStart(3, '0')}`, { class: 's', anomaly: 'normal' }),
      );
      const manifest = generateSplitManifest({ ...BASE_OPTIONS, items });
      expect(manifest.assignments).toHaveLength(size);
      const counted = manifest.strata[0].train + manifest.strata[0].val + manifest.strata[0].test;
      expect(counted).toBe(size);
    }
  });

  it('handles an empty item list', () => {
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items: [] });
    expect(manifest.assignments).toEqual([]);
    expect(manifest.strata).toEqual([]);
    expect(manifest.manifestHash).toBe(computeManifestHash(manifest));
  });

  it('handles a single class', () => {
    const items = Array.from({ length: 10 }, (_unused, index) =>
      makeItem(`only/${String(index).padStart(3, '0')}`, { class: 'only', anomaly: 'normal' }),
    );
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items });
    expect(manifest.strata).toHaveLength(1);
    expect(manifest.strata[0]).toMatchObject({ total: 10, train: 6, val: 2, test: 2 });
  });
});

/* ------------------------------------------------------------------ *
 * 5. Capture grouping (leakage-aware)
 * ------------------------------------------------------------------ */

describe('split manifest — capture grouping', () => {
  it('keeps every item of a capture group in the SAME split', () => {
    const items = Array.from({ length: 20 }, (_unused, index) =>
      makeItem(`g/${String(index).padStart(3, '0')}`, {
        class: 'g',
        anomaly: 'normal',
        group: `session-${index % 4}`,
      }),
    );
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items });

    const splitByGroup = new Map<string, Set<string>>();
    for (const assignment of manifest.assignments) {
      const group = items.find((item) => item.id === assignment.id)?.group ?? '';
      const splits = splitByGroup.get(group) ?? new Set<string>();
      splits.add(assignment.split);
      splitByGroup.set(group, splits);
    }
    for (const [, splits] of splitByGroup) {
      expect(splits.size).toBe(1);
    }
  });

  it('assigns a too-large capture group wholly to one split and records the overflow', () => {
    // 10 items: one group of 9 (too big for any quota: 6/2/2) + one singleton.
    const items = [
      ...Array.from({ length: 9 }, (_unused, index) =>
        makeItem(`big/${String(index).padStart(3, '0')}`, {
          class: 'big',
          anomaly: 'normal',
          group: 'session-big',
        }),
      ),
      makeItem('small/000', { class: 'big', anomaly: 'normal', group: 'session-small' }),
    ];
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items });

    const bigSplits = new Set(
      manifest.assignments.filter((a) => a.id.startsWith('big/')).map((a) => a.split),
    );
    expect(bigSplits.size).toBe(1);
    expect([...bigSplits]).toEqual(['train']);

    const overflow = manifest.notes.filter((note) =>
      note.reason.startsWith(CAPTURE_GROUP_OVERFLOW_REASON_PREFIX),
    );
    expect(overflow).toHaveLength(1);
    expect(overflow[0].id).toContain('session-big');
    expect(overflow[0].reason).toContain('capture-group-overflow:');
    expect(manifest.strata[0]).toMatchObject({ total: 10, train: 9, val: 1, test: 0 });
  });

  it('keeps near-duplicate groups together (stub hook, specs 004/005 own the real guard)', () => {
    const items = Array.from({ length: 10 }, (_unused, index) =>
      makeItem(`nd/${String(index).padStart(3, '0')}`, { class: 'nd', anomaly: 'normal' }),
    );
    const manifest = generateSplitManifest({
      ...BASE_OPTIONS,
      items,
      nearDuplicateGroups: (candidates) =>
        new Map(candidates.map((item) => [item.id, 'near-duplicate-cluster'])),
    });
    const splits = new Set(manifest.assignments.map((a) => a.split));
    expect(splits.size).toBe(1);
  });
});

/* ------------------------------------------------------------------ *
 * 6. Tamper detection
 * ------------------------------------------------------------------ */

describe('split manifest — tamper detection', () => {
  it('reports the tampered file, naming both hashes', () => {
    const items = makeDataset();
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items });
    const tamperedId = manifest.assignments[3].id;
    const tamperedHash = 'f'.repeat(64);

    const expectedHashes = new Map(
      manifest.assignments.map((a) => [a.id, a.id === tamperedId ? tamperedHash : a.sha256]),
    );
    const result = validateSplitManifestHashes(manifest, expectedHashes);

    expect(result.ok).toBe(false);
    expect(result.divergences).toHaveLength(1);
    const divergence = result.divergences[0];
    expect(divergence.kind).toBe('image-hash-mismatch');
    expect(divergence.id).toBe(tamperedId);
    expect(divergence.expectedSha256).toBe(manifest.assignments[3].sha256);
    expect(divergence.actualSha256).toBe(tamperedHash);
    expect(divergence.path).toBe(manifest.assignments[3].path);
    expect(divergence.message).toContain(manifest.assignments[3].path);
    expect(divergence.message).toContain(tamperedHash);
  });

  it('detects a tampered image on disk', async () => {
    const root = await mkdtemp(path.join(tmpdir(), 'vision-lens-splits-'));
    const bytes = Buffer.from('not the bytes the manifest was built from');
    await writeFile(path.join(root, 'a.JPG'), bytes);

    const manifest = generateSplitManifest({
      ...BASE_OPTIONS,
      items: [makeItem('a', { sha256: 'a'.repeat(64), path: 'a.JPG' })],
    });

    const result = await validateSplitManifest(manifest, { root });
    expect(result.ok).toBe(false);
    const divergence = result.divergences[0];
    expect(divergence.kind).toBe('image-hash-mismatch');
    expect(divergence.path).toBe('a.JPG');
    expect(divergence.actualSha256).toBe(createHash('sha256').update(bytes).digest('hex'));
    expect(divergence.expectedSha256).toBe('a'.repeat(64));
  });

  it('reports a manifest whose own hash does not match its content', () => {
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items: makeDataset() });
    const tampered: SplitManifest = { ...manifest, manifestHash: '0'.repeat(64) };
    const result = validateSplitManifestHashes(tampered);
    expect(result.ok).toBe(false);
    expect(result.divergences[0].kind).toBe('manifest-hash-mismatch');
    expect(result.divergences[0].actualSha256).toBe(manifest.manifestHash);
  });
});

/* ------------------------------------------------------------------ *
 * 7. Hash pinning
 * ------------------------------------------------------------------ */

describe('split manifest — hash pinning', () => {
  it('pins manifestHash to sha256 over the canonical JSON without the hash field', () => {
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items: makeDataset() });
    const { manifestHash, ...rest } = manifest;
    const expected = createHash('sha256').update(canonicalJson(rest)).digest('hex');
    expect(manifestHash).toBe(expected);
    expect(manifestHash).toMatch(/^[0-9a-f]{64}$/);
  });

  it('changes the manifestHash when any content changes', () => {
    const items = makeDataset();
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items });
    const changed = generateSplitManifest({
      ...BASE_OPTIONS,
      items: items.map((item) =>
        item.id === items[0].id ? { ...item, sha256: 'b'.repeat(64) } : item,
      ),
    });
    expect(changed.manifestHash).not.toBe(manifest.manifestHash);
  });
});

/* ------------------------------------------------------------------ *
 * 8. Notes channel
 * ------------------------------------------------------------------ */

describe('split manifest — notes channel', () => {
  it('excludes a noted item from scoring but keeps it in the manifest', () => {
    const items = makeDataset();
    const notedId = items[5].id;
    const manifest = generateSplitManifest({
      ...BASE_OPTIONS,
      items,
      notes: [{ id: notedId, reason: 'known-bad: capture is blurred' }],
    });

    expect(manifest.assignments.some((a) => a.id === notedId)).toBe(false);
    expect(manifest.assignments).toHaveLength(items.length - 1);
    expect(manifest.notes).toContainEqual({
      id: notedId,
      reason: 'known-bad: capture is blurred',
    });
    expect(manifest.notes.some((note) => note.id === notedId)).toBe(true);
  });

  it('keeps structural notes (capture-group overflow) in the same channel', () => {
    const items = Array.from({ length: 9 }, (_unused, index) =>
      makeItem(`big/${String(index).padStart(3, '0')}`, {
        class: 'big',
        anomaly: 'normal',
        group: 'session-big',
      }),
    );
    const manifest = generateSplitManifest({ ...BASE_OPTIONS, items });
    expect(manifest.notes.length).toBeGreaterThan(0);
    expect(manifest.notes[0].reason.startsWith(CAPTURE_GROUP_OVERFLOW_REASON_PREFIX)).toBe(true);
  });
});

/* ------------------------------------------------------------------ *
 * PRNG
 * ------------------------------------------------------------------ */

describe('split manifest — PRNG', () => {
  it('mulberry32 is a pure function of its seed', () => {
    const a = mulberry32(42);
    const b = mulberry32(42);
    const c = mulberry32(43);
    const first = [a(), a(), a()];
    expect([b(), b(), b()]).toEqual(first);
    expect(c()).not.toBe(first[0]);
  });

  it('mulberry32 stays in [0, 1)', () => {
    const rand = mulberry32(1234);
    for (let index = 0; index < 1000; index += 1) {
      const value = rand();
      expect(value).toBeGreaterThanOrEqual(0);
      expect(value).toBeLessThan(1);
    }
  });
});
